"""Grade records."""


class Grade:
    def __init__(self, student, score):
        self.student = student
        self.score = score

    def __repr__(self):
        return "Grade(%r, %r)" % (self.student, self.score)


ROWS = [('ana', 46), ('ben', 22), ('dev', 38), ('ana', 58), ('ben', 48)]


def load_grades():
    """Yield the stored grades one at a time."""
    for student, score in ROWS:
        yield Grade(student, score)


def feed_grades():
    """Endless feed of grades: repeats the stored rows for ever."""
    while True:
        for student, score in ROWS:
            yield Grade(student, score)
